import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { HeresyGameManager } from '../src/heresyGameManager.js';

function fixture(count=5){const dir=fs.mkdtempSync(path.join(os.tmpdir(),'heresy-v1-'));let now=1_000_000;const manager=new HeresyGameManager({databasePath:path.join(dir,'game.db'),now:()=>now,random:()=>0.9});const {code}=manager.create({playerCode:'p0',name:'P0'});for(let i=1;i<count;i++){manager.join({code,playerCode:`p${i}`,name:`P${i}`});manager.ready(code,`p${i}`,true);}return{manager,code,close(){manager.close();fs.rmSync(dir,{recursive:true,force:true});}};}

test('locked compositions are exact and roles come from JSON',()=>{const f=fixture();try{for(let n=5;n<=12;n++){const ids=f.manager.presetFor(n);assert.equal(ids.length,n);for(const id of ids)assert.ok(f.manager.role(id));const specials=ids.filter(x=>x!=='imperial-citizen');assert.equal(new Set(specials).size,specials.length);}assert.deepEqual(f.manager.presetFor(5),['murderer','priest','interrogator','chirurgeon','imperial-citizen']);}finally{f.close();}});

test('state never exposes numeric drift',()=>{const f=fixture();try{f.manager.start(f.code,'p0');const state=f.manager.state(f.code,'p0');assert.equal(JSON.stringify(state).includes('"drift"'),false);assert.ok(state.me.role?.id);assert.equal(state.players.filter(p=>p.role).length,1);}finally{f.close();}});

test('lobby state does not expose role composition but does expose compositionLabel',()=>{const f=fixture();try{const state=f.manager.state(f.code,'p0');assert.equal(state.phase,'lobby');assert.equal('composition' in state,false);assert.equal(state.compositionLabel,'5-operative doctrine');assert.equal(JSON.stringify(state).includes('Murderer'),false);assert.equal(JSON.stringify(state).includes('Priest'),false);assert.equal(state.players.some(p=>p.role),false);}finally{f.close();}});

test('catalyst converts only a Black-zone target and failure is silent',()=>{const f=fixture(10);try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const recruiter=f.manager.players(f.code).find(p=>p.role_id==='recruiter'),target=f.manager.players(f.code).find(p=>p.faction==='loyalist');f.manager.submitAction(f.code,recruiter.player_code,{targetCode:target.player_code});f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,target.player_code).faction,'loyalist');f.manager.db.prepare("UPDATE hr_games SET phase='night',round=2 WHERE code=?").run(f.code);f.manager.db.prepare('UPDATE hr_players SET drift=20,skip_next_night=1 WHERE game_code=? AND player_code=?').run(f.code,target.player_code);f.manager.submitAction(f.code,recruiter.player_code,{targetCode:target.player_code});f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,target.player_code).faction,'heretic');}finally{f.close();}});

// ── Tiered Lynch (tiered-lynch.md v1.0.0) ──────────────────────────────────
// Supersedes the old consecutive-day escalation entirely: outcome is
// decided same-day by what fraction of LIVING votes the leader clears.
// >=60% (ceil) executes outright; any positive count below that
// interrogates instead — repeatably, with no drift cost beyond the cripple
// tier (the old wrong/right-interrogation drift rows are gone).

test('Tiered Lynch: below 60% interrogates — no drift to voters, no drift to target, skips next night',()=>{const f=fixture();try{f.manager.start(f.code,'p0');const target=f.manager.players(f.code).find(p=>p.faction==='loyalist'),voters=f.manager.players(f.code).filter(p=>p.player_code!==target.player_code).slice(0,2);f.manager.db.prepare("UPDATE hr_games SET phase='day',round=2,day_stage='vote' WHERE code=?").run(f.code);for(const p of voters)f.manager.vote(f.code,p.player_code,target.player_code);f.manager.resolve(f.code,true);assert.equal(f.manager.game(f.code).phase,'night','2/5=40%, below threshold — interrogate, not execute');assert.equal(f.manager.player(f.code,target.player_code).cripple_tier,1);assert.equal(f.manager.player(f.code,target.player_code).alive,1);assert.equal(f.manager.player(f.code,target.player_code).skip_next_night,1,'target loses their next night action');for(const p of voters)assert.equal(f.manager.player(f.code,p.player_code).drift,0,'no drift to voters — interrogation has no drift cost');assert.equal(f.manager.player(f.code,target.player_code).drift,0,'no drift to target either');const event=f.manager.db.prepare("SELECT payload FROM hr_events WHERE game_code=? AND type='day-resolution' ORDER BY id DESC LIMIT 1").get(f.code);assert.equal(JSON.parse(event.payload).outcome,'interrogate');assert.equal(JSON.parse(event.payload).witnessedDrift,0);}finally{f.close();}});

test('Tiered Lynch: interrogating a Heretic target also carries no drift (cleansing rule removed)',()=>{const f=fixture();try{f.manager.start(f.code,'p0');const target=f.manager.players(f.code).find(p=>p.faction==='heretic'),voters=f.manager.players(f.code).filter(p=>p.player_code!==target.player_code).slice(0,2);f.manager.db.prepare('UPDATE hr_players SET drift=5 WHERE game_code=?').run(f.code);f.manager.db.prepare("UPDATE hr_games SET phase='day',round=2,day_stage='vote' WHERE code=?").run(f.code);for(const p of voters)f.manager.vote(f.code,p.player_code,target.player_code);f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,target.player_code).cripple_tier,1);assert.ok(f.manager.players(f.code).filter(p=>p.alive).every(p=>p.drift===5),'drift unchanged for everyone — no cleansing');const event=f.manager.db.prepare("SELECT payload FROM hr_events WHERE game_code=? AND type='day-resolution' ORDER BY id DESC LIMIT 1").get(f.code);assert.equal(JSON.parse(event.payload).witnessedDrift,0);}finally{f.close();}});

test('Tiered Lynch: 5p exact boundary — 3/5 (60%) executes outright, no prior day needed',()=>{const f=fixture();try{f.manager.start(f.code,'p0');const target=f.manager.players(f.code).find(p=>p.faction==='loyalist'),voters=f.manager.players(f.code).filter(p=>p.player_code!==target.player_code).slice(0,3);f.manager.db.prepare("UPDATE hr_games SET phase='day',round=2,day_stage='vote' WHERE code=?").run(f.code);for(const p of voters)f.manager.vote(f.code,p.player_code,target.player_code);f.manager.resolve(f.code,true);const after=f.manager.player(f.code,target.player_code);assert.equal(after.alive,0,'3/5=60% clears the threshold on the FIRST day, not the second');assert.equal(after.cripple_tier,3);assert.ok(f.manager.historyMessages(f.code,'p0','public').messages.some(m=>/revealed loyalist/.test(m.body)));const event=f.manager.db.prepare("SELECT payload FROM hr_events WHERE game_code=? AND type='day-resolution' ORDER BY id DESC LIMIT 1").get(f.code);assert.equal(JSON.parse(event.payload).outcome,'lynch');}finally{f.close();}});

test('Tiered Lynch: 6p at 4/6 (67%) executes; 3/6 (50%) only interrogates',()=>{const f=fixture(6);try{f.manager.start(f.code,'p0');const target=f.manager.players(f.code).find(p=>p.faction==='loyalist'&&p.player_code!=='p0'),voters=f.manager.players(f.code).filter(p=>p.player_code!==target.player_code);f.manager.db.prepare("UPDATE hr_games SET phase='day',round=2,day_stage='vote' WHERE code=?").run(f.code);for(const p of voters.slice(0,3))f.manager.vote(f.code,p.player_code,target.player_code);f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,target.player_code).alive,1,'3/6=50% — below the ceil(6*0.6)=4 threshold, interrogate only');f.manager.db.prepare("UPDATE hr_games SET phase='day',round=3,day_stage='vote' WHERE code=?").run(f.code);for(const p of voters.slice(0,4))f.manager.vote(f.code,p.player_code,target.player_code);f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,target.player_code).alive,0,'4/6=67% clears the threshold');}finally{f.close();}});

// ── Tiered Lynch v1.1.0: consecutive-interrogation escalation ─────────────
// The same suspect interrogated on two CONSECUTIVE days now escalates to a
// kill on the second day — the cabal gets exactly one probe cycle to
// defend a suspect before the table's second look is a verdict, not
// another probe. This supersedes v1.0.0's "repeatable, never escalates"
// behavior for the specific same-target-two-days-running case; a target
// hit non-consecutively (with any gap — a skip day, a different target in
// between, or a direct kill) still just gets a fresh interrogation.

test('Tiered Lynch v1.1.0: same suspect interrogated two consecutive days — day 2 escalates to a kill',()=>{const f=fixture();try{f.manager.start(f.code,'p0');const target=f.manager.players(f.code).find(p=>p.faction==='loyalist'&&p.player_code!=='p0'),voters=f.manager.players(f.code).filter(p=>p.player_code!==target.player_code).slice(0,2);f.manager.db.prepare("UPDATE hr_games SET phase='day',round=2,day_stage='vote' WHERE code=?").run(f.code);for(const p of voters)f.manager.vote(f.code,p.player_code,target.player_code);f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,target.player_code).cripple_tier,1,'day 2: first interrogation, tier 1');assert.equal(f.manager.player(f.code,target.player_code).alive,1);f.manager.db.prepare("UPDATE hr_games SET phase='night',round=2 WHERE code=?").run(f.code);f.manager.resolve(f.code,true);f.manager.db.prepare("UPDATE hr_games SET phase='day',round=3,day_stage='vote' WHERE code=?").run(f.code);for(const p of voters)f.manager.vote(f.code,p.player_code,target.player_code);f.manager.resolve(f.code,true);const after=f.manager.player(f.code,target.player_code);assert.equal(after.alive,0,'day 3: same suspect again — escalates to execution, not a third interrogation');assert.equal(after.cripple_tier,3);assert.ok(f.manager.historyMessages(f.code,'p0','public').messages.some(m=>/revealed loyalist/.test(m.body)),'alignment revealed, same as a >=60% kill');const event=f.manager.db.prepare("SELECT payload FROM hr_events WHERE game_code=? AND type='day-resolution' ORDER BY id DESC LIMIT 1").get(f.code);assert.equal(JSON.parse(event.payload).outcome,'lynch');}finally{f.close();}});

test('Tiered Lynch v1.1.0: a skip day in between resets the escalation — third day is a fresh interrogation',()=>{const f=fixture();try{f.manager.start(f.code,'p0');const target=f.manager.players(f.code).find(p=>p.faction==='loyalist'&&p.player_code!=='p0'),voters=f.manager.players(f.code).filter(p=>p.player_code!==target.player_code).slice(0,2),everyone=f.manager.players(f.code);f.manager.db.prepare("UPDATE hr_games SET phase='day',round=2,day_stage='vote' WHERE code=?").run(f.code);for(const p of voters)f.manager.vote(f.code,p.player_code,target.player_code);f.manager.resolve(f.code,true);f.manager.db.prepare("UPDATE hr_games SET phase='night',round=2 WHERE code=?").run(f.code);f.manager.resolve(f.code,true);f.manager.db.prepare("UPDATE hr_games SET phase='day',round=3,day_stage='vote' WHERE code=?").run(f.code);for(const p of everyone)f.manager.vote(f.code,p.player_code,'skip');f.manager.resolve(f.code,true);f.manager.db.prepare("UPDATE hr_games SET phase='night',round=3 WHERE code=?").run(f.code);f.manager.resolve(f.code,true);f.manager.db.prepare("UPDATE hr_games SET phase='day',round=4,day_stage='vote' WHERE code=?").run(f.code);for(const p of voters)f.manager.vote(f.code,p.player_code,target.player_code);f.manager.resolve(f.code,true);const after=f.manager.player(f.code,target.player_code);assert.equal(after.alive,1,'the intervening skip day broke the streak — round 4 is a fresh interrogation, not an escalation');const event=f.manager.db.prepare("SELECT payload FROM hr_events WHERE game_code=? AND type='day-resolution' ORDER BY id DESC LIMIT 1").get(f.code);assert.equal(JSON.parse(event.payload).outcome,'interrogate');}finally{f.close();}});

test('Tiered Lynch v1.1.0: a different target interrogated in between resets the escalation for the original suspect',()=>{const f=fixture(6);try{f.manager.start(f.code,'p0');const loyalists=f.manager.players(f.code).filter(p=>p.faction==='loyalist'),targetA=loyalists[0],targetB=loyalists[1],voters=f.manager.players(f.code).filter(p=>p.player_code!==targetA.player_code&&p.player_code!==targetB.player_code).slice(0,2);f.manager.db.prepare("UPDATE hr_games SET phase='day',round=2,day_stage='vote' WHERE code=?").run(f.code);for(const p of voters)f.manager.vote(f.code,p.player_code,targetA.player_code);f.manager.resolve(f.code,true);f.manager.db.prepare("UPDATE hr_games SET phase='night',round=2 WHERE code=?").run(f.code);f.manager.resolve(f.code,true);f.manager.db.prepare("UPDATE hr_games SET phase='day',round=3,day_stage='vote' WHERE code=?").run(f.code);for(const p of voters)f.manager.vote(f.code,p.player_code,targetB.player_code);f.manager.resolve(f.code,true);f.manager.db.prepare("UPDATE hr_games SET phase='night',round=3 WHERE code=?").run(f.code);f.manager.resolve(f.code,true);f.manager.db.prepare("UPDATE hr_games SET phase='day',round=4,day_stage='vote' WHERE code=?").run(f.code);for(const p of voters)f.manager.vote(f.code,p.player_code,targetA.player_code);f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,targetA.player_code).alive,1,'targetB breaking in between means targetA is not "the previous day\'s leader" on round 4 — fresh interrogation');}finally{f.close();}});

test('Tiered Lynch v1.1.0: a >=60% kill does not carry an escalation into the next day',()=>{const f=fixture();try{f.manager.start(f.code,'p0');const targetA=f.manager.players(f.code).find(p=>p.faction==='loyalist'&&p.player_code!=='p0'),targetB=f.manager.players(f.code).find(p=>p.faction==='loyalist'&&p.player_code!=='p0'&&p.player_code!==targetA.player_code),voters=f.manager.players(f.code).filter(p=>p.player_code!==targetA.player_code).slice(0,3);f.manager.db.prepare("UPDATE hr_games SET phase='day',round=2,day_stage='vote' WHERE code=?").run(f.code);for(const p of voters)f.manager.vote(f.code,p.player_code,targetA.player_code);f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,targetA.player_code).alive,0,'3/5=60% kills outright on day 2');const twoVoters=f.manager.players(f.code).filter(p=>p.alive&&p.player_code!==targetB.player_code).slice(0,2);f.manager.db.prepare("UPDATE hr_games SET phase='day',round=3,day_stage='vote' WHERE code=?").run(f.code);for(const p of twoVoters)f.manager.vote(f.code,p.player_code,targetB.player_code);f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,targetB.player_code).alive,1,'a fresh target the day after a kill is just a normal interrogation — no residual escalation state');}finally{f.close();}});

test('Tiered Lynch v1.1.0: atRiskTarget is exposed in state()/spectate() after an interrogation, and clears once the streak breaks',()=>{const f=fixture();try{f.manager.start(f.code,'p0');const target=f.manager.players(f.code).find(p=>p.faction==='loyalist'&&p.player_code!=='p0'),voters=f.manager.players(f.code).filter(p=>p.player_code!==target.player_code).slice(0,2),bystander=f.manager.players(f.code).find(p=>p.player_code!==target.player_code&&!voters.some(v=>v.player_code===p.player_code));f.manager.db.prepare("UPDATE hr_games SET phase='day',round=2,day_stage='vote' WHERE code=?").run(f.code);for(const p of voters)f.manager.vote(f.code,p.player_code,target.player_code);f.manager.resolve(f.code,true);assert.equal(f.manager.state(f.code,bystander.player_code).atRiskTarget,target.player_code,'publicly visible — anyone can see who is one interrogation away from execution');assert.equal(f.manager.spectate(f.code).atRiskTarget,target.player_code);f.manager.db.prepare("UPDATE hr_games SET phase='night',round=2 WHERE code=?").run(f.code);f.manager.resolve(f.code,true);f.manager.db.prepare("UPDATE hr_games SET phase='day',round=3,day_stage='vote' WHERE code=?").run(f.code);for(const p of voters)f.manager.vote(f.code,p.player_code,'skip');f.manager.resolve(f.code,true);assert.equal(f.manager.state(f.code,bystander.player_code).atRiskTarget,null,'a skip day clears the flag');}finally{f.close();}});

test('Tiered Lynch: a target already at T3 still gets interrogated — tier saturates but the night-action skip still fires',()=>{const f=fixture();try{f.manager.start(f.code,'p0');const target=f.manager.players(f.code).find(p=>p.faction==='loyalist'&&p.player_code!=='p0'),voters=f.manager.players(f.code).filter(p=>p.player_code!==target.player_code).slice(0,2);f.manager.db.prepare('UPDATE hr_players SET cripple_tier=3 WHERE game_code=? AND player_code=?').run(f.code,target.player_code);f.manager.db.prepare("UPDATE hr_games SET phase='day',round=2,day_stage='vote' WHERE code=?").run(f.code);for(const p of voters)f.manager.vote(f.code,p.player_code,target.player_code);f.manager.resolve(f.code,true);assert.equal(f.manager.game(f.code).phase,'night','not blocked — the old T3 hard-block is gone');const after=f.manager.player(f.code,target.player_code);assert.equal(after.cripple_tier,3,'capped, does not overflow past 3');assert.equal(after.skip_next_night,1,'still loses the night action');assert.equal(after.alive,1);const event=f.manager.db.prepare("SELECT payload FROM hr_events WHERE game_code=? AND type='day-resolution' ORDER BY id DESC LIMIT 1").get(f.code);assert.equal(JSON.parse(event.payload).outcome,'interrogate');}finally{f.close();}});

test('Tiered Lynch: tiebreaker (higher drift) still resolves the target when the fraction is below 60%',()=>{const f=fixture();try{f.manager.start(f.code,'p0');const loyalists=f.manager.players(f.code).filter(p=>p.faction==='loyalist'),targetA=loyalists[0],targetB=loyalists[1],voterA=f.manager.players(f.code).find(p=>p.player_code!==targetA.player_code&&p.player_code!==targetB.player_code),voterB=f.manager.players(f.code).find(p=>p.player_code!==targetA.player_code&&p.player_code!==targetB.player_code&&p.player_code!==voterA.player_code);f.manager.db.prepare('UPDATE hr_players SET drift=3 WHERE game_code=? AND player_code=?').run(f.code,targetA.player_code);f.manager.db.prepare('UPDATE hr_players SET drift=9 WHERE game_code=? AND player_code=?').run(f.code,targetB.player_code);f.manager.db.prepare("UPDATE hr_games SET phase='day',round=2,day_stage='vote' WHERE code=?").run(f.code);f.manager.vote(f.code,voterA.player_code,targetA.player_code);f.manager.vote(f.code,voterB.player_code,targetB.player_code);f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,targetB.player_code).cripple_tier,1,'higher-drift target wins the 1-1 tie');assert.equal(f.manager.player(f.code,targetA.player_code).cripple_tier,0);assert.equal(f.manager.player(f.code,targetB.player_code).alive,1,'1/5=20% — nowhere near 60%, so still interrogation, not execution');}finally{f.close();}});

test('Tiered Lynch: full-flow via advance() — Day 2 interrogates below threshold, Day 3 executes once 60% is reached',()=>{const f=fixture();try{f.manager.start(f.code,'p0');const target=f.manager.players(f.code).find(p=>p.faction==='loyalist'&&p.player_code!=='p0'),twoVoters=f.manager.players(f.code).filter(p=>p.player_code!==target.player_code).slice(0,2),threeVoters=f.manager.players(f.code).filter(p=>p.player_code!==target.player_code).slice(0,3);f.manager.advance(f.code,'p0');// Night 1
f.manager.advance(f.code,'p0');// Day 2
assert.equal(f.manager.game(f.code).round,2);for(const p of twoVoters)f.manager.vote(f.code,p.player_code,target.player_code);f.manager.advance(f.code,'p0');assert.equal(f.manager.player(f.code,target.player_code).alive,1);assert.equal(f.manager.player(f.code,target.player_code).cripple_tier,1);f.manager.advance(f.code,'p0');// Day 3
assert.equal(f.manager.game(f.code).round,3);for(const p of threeVoters)f.manager.vote(f.code,p.player_code,target.player_code);f.manager.advance(f.code,'p0');const after=f.manager.player(f.code,target.player_code);assert.equal(after.alive,0,'3/5=60% on Day 3 alone is sufficient — no two-day commitment needed');assert.equal(after.cripple_tier,3);const events=f.manager.db.prepare("SELECT payload FROM hr_events WHERE game_code=? AND type='day-resolution' ORDER BY id").all(f.code);const parsed=events.map(e=>JSON.parse(e.payload));assert.equal(parsed[0].outcome,'skip');assert.equal(parsed[0].reason,'day1-no-vote');assert.equal(parsed[1].outcome,'interrogate');assert.equal(parsed[1].round,2);assert.equal(parsed[2].outcome,'lynch');assert.equal(parsed[2].round,3);}finally{f.close();}});

test('sermon limits are enforced from data',()=>{const f=fixture(6);try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const priest=f.manager.players(f.code).find(p=>p.role_id==='priest'),target=f.manager.players(f.code).find(p=>p.player_code!==priest.player_code);f.manager.db.prepare('INSERT INTO hr_usage VALUES(?,?,?,?)').run(f.code,priest.player_code,'hymn',2);assert.throws(()=>f.manager.submitAction(f.code,priest.player_code,{targetCode:target.player_code,variant:'hymn'}),/limit/);}finally{f.close();}});

test('all dead players share one graveyard and living players are denied',()=>{const f=fixture();try{const dead='p1';f.manager.db.prepare('UPDATE hr_players SET alive=0 WHERE game_code=? AND player_code=?').run(f.code,dead);f.manager.sendMessage(f.code,dead,'graveyard','Ashes remember.');assert.equal(f.manager.historyMessages(f.code,dead,'graveyard').messages.length,1);assert.throws(()=>f.manager.historyMessages(f.code,'p0','graveyard'),/denied/);}finally{f.close();}});

test('sleep reduces drift only when no action was submitted',()=>{const f=fixture(6);try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const citizenLike=f.manager.players(f.code).find(p=>f.manager.role(p.role_id).actions.night?.kind==='sleep');if(citizenLike){f.manager.db.prepare('UPDATE hr_players SET drift=5 WHERE game_code=? AND player_code=?').run(f.code,citizenLike.player_code);f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,citizenLike.player_code).drift,4);}}finally{f.close();}});


test('skip majority stands the day down without drift',()=>{const f=fixture();try{f.manager.start(f.code,'p0');const voters=f.manager.players(f.code).slice(0,3);f.manager.db.prepare("UPDATE hr_games SET phase='day',round=2,day_stage='vote' WHERE code=?").run(f.code);for(const p of voters)f.manager.vote(f.code,p.player_code,'skip');f.manager.resolve(f.code,true);assert.equal(f.manager.game(f.code).phase,'night');assert.ok(f.manager.players(f.code).every(p=>p.drift===0));const event=f.manager.db.prepare("SELECT payload FROM hr_events WHERE game_code=? AND type='day-resolution' ORDER BY id DESC LIMIT 1").get(f.code);assert.equal(JSON.parse(event.payload).outcome,'skip');assert.equal(JSON.parse(event.payload).reason,'skip-majority');}finally{f.close();}});

test('Day 3 Heretics below cap receive the locked spike',()=>{const f=fixture(6);try{f.manager.start(f.code,'p0');const heretic=f.manager.players(f.code).find(p=>p.faction==='heretic');f.manager.applyHereticCap(f.code,3);assert.equal(f.manager.player(f.code,heretic.player_code).drift,3);}finally{f.close();}});

test('Heretic parity ends the game',()=>{const f=fixture();try{f.manager.start(f.code,'p0');const loyalists=f.manager.players(f.code).filter(p=>p.faction==='loyalist');f.manager.db.prepare('UPDATE hr_players SET alive=0 WHERE game_code=? AND player_code IN (?,?,?)').run(f.code,loyalists[0].player_code,loyalists[1].player_code,loyalists[2].player_code);assert.equal(f.manager.finishIfWon(f.code),true);assert.equal(f.manager.game(f.code).winner,'heretic');}finally{f.close();}});

test('admin overview and detail expose actual hidden game state',()=>{const f=fixture();try{f.manager.start(f.code,'p0');f.manager.changeDrift(f.code,'p0',5,'admin-test');const driftEvent=JSON.parse(f.manager.db.prepare("SELECT payload FROM hr_events WHERE game_code=? AND type='drift' ORDER BY id DESC LIMIT 1").get(f.code).payload);assert.equal(driftEvent.before,0);assert.equal(driftEvent.after,5);assert.equal(driftEvent.round,1);assert.equal(driftEvent.phase,'day');const overview=f.manager.adminOverview();const summary=overview.games.find(g=>g.code===f.code);assert.ok(summary);assert.equal(summary.averageDrift,1);assert.equal(summary.maxPlayerDrift,5);assert.ok(overview.roles.length>=5);const detail=f.manager.adminGame(f.code);assert.equal(detail.game.code,f.code);assert.equal(detail.players.length,5);assert.equal(detail.players.find(p=>p.playerCode==='p0').drift,5);assert.equal(detail.players.some(p=>p.role&&p.faction&&Number.isInteger(p.drift)),true);assert.ok(Array.isArray(detail.messages));assert.ok(Array.isArray(detail.events));}finally{f.close();}});

test('L1: every living citizen auto-drifts -1 per night (floor 0)',()=>{const f=fixture();try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const citizen=f.manager.players(f.code).find(p=>p.role_id==='imperial-citizen');assert.ok(citizen,'citizen exists');assert.equal(citizen.drift,0);f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,citizen.player_code).drift,0,'floors at 0');f.manager.db.prepare("UPDATE hr_games SET phase='night',round=2 WHERE code=?").run(f.code);f.manager.db.prepare('UPDATE hr_players SET drift=3 WHERE game_code=? AND player_code=?').run(f.code,citizen.player_code);f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,citizen.player_code).drift,2,'reduces from 3 to 2');}finally{f.close();}});

test('L1: crippled citizen still sleeps (drift -1)',()=>{const f=fixture();try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const citizen=f.manager.players(f.code).find(p=>p.role_id==='imperial-citizen');f.manager.db.prepare('UPDATE hr_players SET drift=5,cripple_tier=2 WHERE game_code=? AND player_code=?').run(f.code,citizen.player_code);f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,citizen.player_code).drift,4,'crippled citizen still gets sleep');}finally{f.close();}});

test('L1: dead citizen does not sleep',()=>{const f=fixture();try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const citizen=f.manager.players(f.code).find(p=>p.role_id==='imperial-citizen');f.manager.db.prepare('UPDATE hr_players SET drift=3,alive=0 WHERE game_code=? AND player_code=?').run(f.code,citizen.player_code);f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,citizen.player_code).drift,3,'dead citizen unchanged');}finally{f.close();}});

test('L1: citizen cannot submit a night action',()=>{const f=fixture();try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const citizen=f.manager.players(f.code).find(p=>p.role_id==='imperial-citizen');assert.throws(()=>f.manager.submitAction(f.code,citizen.player_code,{targetCode:'p0'}),/no active action/);}finally{f.close();}});

test('L3: protect blocks night kill — attacker wastes action',()=>{const f=fixture();try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const chirurgeon=f.manager.players(f.code).find(p=>p.role_id==='chirurgeon'),murderer=f.manager.players(f.code).find(p=>p.role_id==='murderer'),target=f.manager.players(f.code).find(p=>p.faction==='loyalist'&&p.role_id!=='chirurgeon');f.manager.submitAction(f.code,chirurgeon.player_code,{targetCode:target.player_code});f.manager.submitAction(f.code,murderer.player_code,{targetCode:target.player_code});f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,target.player_code).alive,1,'target survived');assert.equal(f.manager.player(f.code,chirurgeon.player_code).drift,1,'chirurgeon paid drift');}finally{f.close();}});

test('L3: protect blocks heretical-catalyst — catalyst fails silently',()=>{const f=fixture(10);try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const chirurgeon=f.manager.players(f.code).find(p=>p.role_id==='chirurgeon'),recruiter=f.manager.players(f.code).find(p=>p.role_id==='recruiter'),loyalist=f.manager.players(f.code).find(p=>p.faction==='loyalist'&&p.role_id!=='chirurgeon');f.manager.db.prepare('UPDATE hr_players SET drift=20 WHERE game_code=? AND player_code=?').run(f.code,loyalist.player_code);f.manager.submitAction(f.code,chirurgeon.player_code,{targetCode:loyalist.player_code});f.manager.submitAction(f.code,recruiter.player_code,{targetCode:loyalist.player_code});f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,loyalist.player_code).faction,'loyalist','catalyst was blocked');}finally{f.close();}});

test('L3: rotation rule rejects same target on consecutive nights',()=>{const f=fixture();try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const chirurgeon=f.manager.players(f.code).find(p=>p.role_id==='chirurgeon'),target=f.manager.players(f.code).find(p=>p.faction==='loyalist'&&p.role_id!=='chirurgeon');f.manager.submitAction(f.code,chirurgeon.player_code,{targetCode:target.player_code});f.manager.resolve(f.code,true);f.manager.db.prepare("UPDATE hr_games SET phase='night',round=2 WHERE code=?").run(f.code);assert.throws(()=>f.manager.submitAction(f.code,chirurgeon.player_code,{targetCode:target.player_code}),/consecutive nights/);}finally{f.close();}});

test('L3: rotation allows same target after a gap (night 1 → night 3)',()=>{const f=fixture();try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const chirurgeon=f.manager.players(f.code).find(p=>p.role_id==='chirurgeon'),target=f.manager.players(f.code).find(p=>p.faction==='loyalist'&&p.role_id!=='chirurgeon'),other=f.manager.players(f.code).find(p=>p.player_code!==chirurgeon.player_code&&p.player_code!==target.player_code);f.manager.submitAction(f.code,chirurgeon.player_code,{targetCode:target.player_code});f.manager.resolve(f.code,true);f.manager.db.prepare("UPDATE hr_games SET phase='night',round=2 WHERE code=?").run(f.code);f.manager.submitAction(f.code,chirurgeon.player_code,{targetCode:other.player_code});f.manager.resolve(f.code,true);f.manager.db.prepare("UPDATE hr_games SET phase='night',round=3 WHERE code=?").run(f.code);assert.doesNotThrow(()=>f.manager.submitAction(f.code,chirurgeon.player_code,{targetCode:target.player_code}));}finally{f.close();}});

