test('L5: no L3 regression — existing chirurgeon protect still works',()=>{const f=fixture();try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const chirurgeon=f.manager.players(f.code).find(p=>p.role_id==='chirurgeon'),murderer=f.manager.players(f.code).find(p=>p.role_id==='murderer'),target=f.manager.players(f.code).find(p=>p.faction==='loyalist'&&p.role_id!=='chirurgeon');f.manager.submitAction(f.code,chirurgeon.player_code,{targetCode:target.player_code});f.manager.submitAction(f.code,murderer.player_code,{targetCode:target.player_code});f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,target.player_code).alive,1,'target survived via chirurgeon protect');assert.equal(f.manager.player(f.code,chirurgeon.player_code).drift,1,'chirurgeon paid drift');}finally{f.close();}});

function fixtureL4(randomFn,count=8){const dir=fs.mkdtempSync(path.join(os.tmpdir(),'heresy-l4-'));let now=1_000_000;const manager=new HeresyGameManager({databasePath:path.join(dir,'game.db'),now:()=>now,random:randomFn});const{code}=manager.create({playerCode:'p0',name:'P0'});for(let i=1;i<count;i++){manager.join({code,playerCode:`p${i}`,name:`P${i}`});manager.ready(code,`p${i}`,true);}return{manager,code,close(){manager.close();fs.rmSync(dir,{recursive:true,force:true});}};}

function setupL4Target(f,targetDrift,skipTargetSleep=false){f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const players=f.manager.players(f.code),l4=players[6],target=players[7];f.manager.db.prepare('UPDATE hr_players SET role_id=?,faction=? WHERE game_code=? AND player_code=?').run('novice-psychic','loyalist',f.code,l4.player_code);f.manager.db.prepare('UPDATE hr_players SET role_id=?,faction=? WHERE game_code=? AND player_code=?').run('imperial-citizen','loyalist',f.code,target.player_code);f.manager.db.prepare('UPDATE hr_players SET drift=? WHERE game_code=? AND player_code=?').run(targetDrift,f.code,target.player_code);if(skipTargetSleep)f.manager.db.prepare('UPDATE hr_players SET skip_next_night=1 WHERE game_code=? AND player_code=?').run(f.code,target.player_code);return{l4,target};}

test('L4: novice-psychic investigates a Green-zone target returns Green string',()=>{const f=fixture(8);try{const{l4,target}=setupL4Target(f,0);f.manager.submitAction(f.code,l4.player_code,{targetCode:target.player_code});f.manager.resolve(f.code,true);const msgs=f.manager.db.prepare("SELECT body FROM hr_messages WHERE game_code=? AND channel='private' AND recipient_code=?").all(f.code,l4.player_code);const greenHint=f.manager.hints(f.code).green;assert.ok(msgs.some(m=>m.body===greenHint),'L4 received green hint');assert.equal(msgs.length,2,'L4 received role announcement + investigation result');const otherMsgs=f.manager.db.prepare("SELECT body FROM hr_messages WHERE game_code=? AND channel='private' AND recipient_code!=?").all(f.code,l4.player_code);assert.ok(!otherMsgs.some(m=>m.body===greenHint),'No other player received the hint');}finally{f.close();}});

test('L4: novice-psychic investigating Yellow target — 100 rolls, noise rate ≈ 10%',()=>{let flips=0;const ROLLS=100;for(let i=0;i<ROLLS;i++){const f=fixtureL4(()=>i/ROLLS);try{const{l4,target}=setupL4Target(f,6);f.manager.submitAction(f.code,l4.player_code,{targetCode:target.player_code});f.manager.resolve(f.code,true);const msgs=f.manager.db.prepare("SELECT body FROM hr_messages WHERE game_code=? AND channel='private' AND recipient_code=?").all(f.code,l4.player_code);const yellowHint=f.manager.hints(f.code).yellow;if(msgs[1]?.body!==yellowHint)flips++;}finally{f.close();}}assert.ok(flips>=5&&flips<=15,`Expected ~10 flips, got ${flips}`);});

test('L4: novice-psychic investigating Orange target — 100 rolls, noise rate ≈ 20%',()=>{let flips=0;const ROLLS=100;for(let i=0;i<ROLLS;i++){const f=fixtureL4(()=>i/ROLLS);try{const{l4,target}=setupL4Target(f,11);f.manager.submitAction(f.code,l4.player_code,{targetCode:target.player_code});f.manager.resolve(f.code,true);const msgs=f.manager.db.prepare("SELECT body FROM hr_messages WHERE game_code=? AND channel='private' AND recipient_code=?").all(f.code,l4.player_code);const orangeHint=f.manager.hints(f.code).orange;if(msgs[1]?.body!==orangeHint)flips++;}finally{f.close();}}assert.ok(flips>=12&&flips<=28,`Expected ~20 flips, got ${flips}`);});

test('L4: novice-psychic investigating Black target — flips are always Red (only adjacent zone)',()=>{let flips=0,allRed=true;const ROLLS=100;for(let i=0;i<ROLLS;i++){const f=fixtureL4(()=>i/ROLLS);try{const{l4,target}=setupL4Target(f,20,true);f.manager.submitAction(f.code,l4.player_code,{targetCode:target.player_code});f.manager.resolve(f.code,true);const msgs=f.manager.db.prepare("SELECT body FROM hr_messages WHERE game_code=? AND channel='private' AND recipient_code=?").all(f.code,l4.player_code);const blackHint=f.manager.hints(f.code).black;const redHint=f.manager.hints(f.code).red;const hint=msgs[1]?.body;if(hint!==blackHint){flips++;if(hint!==redHint)allRed=false;}}finally{f.close();}}assert.ok(flips>=40&&flips<=60,`Expected ~50 flips, got ${flips}`);assert.ok(allRed,'All noise flips returned Red (only adjacent zone to Black)');});

test('L4: crippled novice-psychic is silently rejected (no error, no drift)',()=>{const f=fixture(8);try{const{l4,target}=setupL4Target(f,0);f.manager.db.prepare('UPDATE hr_players SET cripple_tier=2 WHERE game_code=? AND player_code=?').run(f.code,l4.player_code);const result=f.manager.submitAction(f.code,l4.player_code,{targetCode:target.player_code});assert.equal(result.silent,true);assert.equal(result.kind,'drift-hint');assert.equal(f.manager.player(f.code,l4.player_code).drift,0,'crippled L4 paid no drift');}finally{f.close();}});

test('L4: novice-psychic self-investigate is rejected',()=>{const f=fixture(8);try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const l4=f.manager.players(f.code)[6];f.manager.db.prepare('UPDATE hr_players SET role_id=?,faction=? WHERE game_code=? AND player_code=?').run('novice-psychic','loyalist',f.code,l4.player_code);assert.throws(()=>f.manager.submitAction(f.code,l4.player_code,{targetCode:l4.player_code}),/Choose another player/);}finally{f.close();}});

test('L4: novice-psychic pays +1 drift when night action resolves',()=>{const f=fixture(8);try{const{l4,target}=setupL4Target(f,0);f.manager.submitAction(f.code,l4.player_code,{targetCode:target.player_code});f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,l4.player_code).drift,1,'L4 paid +1 drift');}finally{f.close();}});

test('T1 cripple recovers after 1 round of no re-interrogation — night action works on next night',()=>{const f=fixture();try{f.manager.start(f.code,'p0');const chirurgeon=f.manager.players(f.code).find(p=>p.role_id==='chirurgeon'),voters=f.manager.players(f.code).filter(p=>p.player_code!==chirurgeon.player_code).slice(0,2);f.manager.db.prepare("UPDATE hr_games SET phase='day',round=2,day_stage='vote' WHERE code=?").run(f.code);for(const p of voters)f.manager.vote(f.code,p.player_code,chirurgeon.player_code);f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,chirurgeon.player_code).cripple_tier,1,'T1 applied');assert.equal(f.manager.player(f.code,chirurgeon.player_code).tier1_until_round,2,'tier1_until_round is current round');assert.equal(f.manager.player(f.code,chirurgeon.player_code).alive,1,'still alive');// Night 2: T1 active — action silently rejected
const target=f.manager.players(f.code).find(p=>p.player_code!==chirurgeon.player_code&&p.alive);
const night1Result=f.manager.submitAction(f.code,chirurgeon.player_code,{targetCode:target.player_code});
assert.equal(night1Result.silent,true,'T1 blocks action');
f.manager.resolve(f.code,true);
// Day 2: T1 should have cleared during night→day transition
assert.equal(f.manager.player(f.code,chirurgeon.player_code).cripple_tier,0,'T1 cleared');
assert.equal(f.manager.player(f.code,chirurgeon.player_code).tier1_until_round,null,'tier1_until_round cleared');
// Night 2: chirurgeon can act again
f.manager.db.prepare("UPDATE hr_games SET phase='night',round=2 WHERE code=?").run(f.code);
const result=f.manager.submitAction(f.code,chirurgeon.player_code,{targetCode:target.player_code});
assert.equal(result.silent,undefined,'action is not silently rejected');
assert.equal(result.kind,'protect','action kind is protect');
  }finally{f.close();}
});

test('L7: Psyker fires kill → target dies, Psyker at +15 drift',()=>{const f=fixture(7);try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const psyker=f.manager.players(f.code).find(p=>p.role_id==='sanctioned-psyker'),target=f.manager.players(f.code).find(p=>p.faction==='heretic'&&p.player_code!==psyker.player_code);f.manager.submitAction(f.code,psyker.player_code,{targetCode:target.player_code});f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,target.player_code).alive,0,'target died');assert.equal(f.manager.player(f.code,psyker.player_code).drift,16,'Psyker at +16 drift (+15 kill +1 witness)');assert.equal(f.manager.usage(f.code,psyker.player_code,'kill'),1,'kill consumed');}finally{f.close();}});

test('L7: Psyker can kill a fellow Loyalist — not faction-locked like Murderer (loyalist-kit.md: "identical to Murderer" is a visibility claim, not a targeting one)',()=>{const f=fixture(7);try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const psyker=f.manager.players(f.code).find(p=>p.role_id==='sanctioned-psyker'),target=f.manager.players(f.code).find(p=>p.faction==='loyalist'&&p.player_code!==psyker.player_code);assert.doesNotThrow(()=>f.manager.submitAction(f.code,psyker.player_code,{targetCode:target.player_code}),'Psyker may target anyone, including a fellow Loyalist');f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,target.player_code).alive,0,'the Loyalist target still dies — Psyker is a blunt instrument, not an intel role');}finally{f.close();}});

test('H1: Murderer still cannot target a fellow Heretic after the target-field fix (regression guard)',()=>{const f=fixture(8);try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const murderer=f.manager.players(f.code).find(p=>p.role_id==='murderer'),fellowHeretic=f.manager.players(f.code).find(p=>p.faction==='heretic'&&p.player_code!==murderer.player_code);assert.throws(()=>f.manager.submitAction(f.code,murderer.player_code,{targetCode:fellowHeretic.player_code}),/not hostile/);}finally{f.close();}});

test('L7: Chirurgeon protect on target → kill blocked, kill consumed, drift still applied',()=>{const f=fixture(7);try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const psyker=f.manager.players(f.code).find(p=>p.role_id==='sanctioned-psyker'),chirurgeon=f.manager.players(f.code).find(p=>p.role_id==='chirurgeon'),target=f.manager.players(f.code).find(p=>p.faction==='heretic');f.manager.submitAction(f.code,chirurgeon.player_code,{targetCode:target.player_code});f.manager.submitAction(f.code,psyker.player_code,{targetCode:target.player_code});f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,target.player_code).alive,1,'target survived');assert.equal(f.manager.player(f.code,psyker.player_code).drift,15,'Psyker paid drift');assert.equal(f.manager.usage(f.code,psyker.player_code,'kill'),1,'kill consumed');}finally{f.close();}});

test('L7: Arbitrator bodyguard redirects kill → Arbitrator dies, Psyker at +15 drift',()=>{const f=fixture(8);try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const psyker=f.manager.players(f.code).find(p=>p.role_id==='sanctioned-psyker'),arbitrator=f.manager.players(f.code).find(p=>p.role_id==='arbitrator'),target=f.manager.players(f.code).find(p=>p.faction==='heretic'&&p.player_code!==psyker.player_code);f.manager.submitAction(f.code,arbitrator.player_code,{targetCode:target.player_code});f.manager.submitAction(f.code,psyker.player_code,{targetCode:target.player_code});f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,arbitrator.player_code).alive,0,'arbitrator died');assert.equal(f.manager.player(f.code,target.player_code).alive,1,'target survived');assert.equal(f.manager.player(f.code,psyker.player_code).drift,16,'Psyker at +16 drift (+15 kill +1 witness)');assert.equal(f.manager.usage(f.code,psyker.player_code,'kill'),1,'kill consumed');}finally{f.close();}});

test('L7: Saboteur trap on Psyker → +20 total drift (15+5), kill NOT consumed',()=>{const f=fixture(8);try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const psyker=f.manager.players(f.code).find(p=>p.role_id==='sanctioned-psyker'),saboteur=f.manager.players(f.code).find(p=>p.role_id==='saboteur'),target=f.manager.players(f.code).find(p=>p.faction==='heretic'&&p.player_code!==psyker.player_code&&p.player_code!==saboteur.player_code);f.manager.submitAction(f.code,saboteur.player_code,{targetCode:psyker.player_code});f.manager.submitAction(f.code,psyker.player_code,{targetCode:target.player_code});f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,psyker.player_code).drift,20,'Psyker at +20 drift');assert.equal(f.manager.usage(f.code,psyker.player_code,'kill'),0,'kill NOT consumed');assert.equal(f.manager.player(f.code,target.player_code).alive,1,'target survived — kill blocked by actor trap');}finally{f.close();}});

test('L7: Execute on Sight — Interrogator T2 scan on Psyker at Red zone kills Psyker, kill NOT consumed',()=>{const f=fixture(7);try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');f.manager.advance(f.code,'p0');const psyker=f.manager.players(f.code).find(p=>p.role_id==='sanctioned-psyker'),interrogator=f.manager.players(f.code).find(p=>p.role_id==='interrogator'),target=f.manager.players(f.code).find(p=>p.faction==='heretic');f.manager.db.prepare('UPDATE hr_players SET drift=15 WHERE game_code=? AND player_code=?').run(f.code,psyker.player_code);f.manager.db.prepare("UPDATE hr_games SET phase='night',round=2 WHERE code=?").run(f.code);f.manager.submitAction(f.code,interrogator.player_code,{targetCode:psyker.player_code,variant:'T2'});f.manager.submitAction(f.code,psyker.player_code,{targetCode:target.player_code});f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,psyker.player_code).alive,0,'Psyker died from Execute on Sight');assert.equal(f.manager.usage(f.code,psyker.player_code,'kill'),0,'kill NOT consumed');assert.equal(f.manager.player(f.code,target.player_code).alive,1,'target survived — kill never fired');}finally{f.close();}});

test('Execute on Sight — Interrogator T2 scan on a Black-zone (20/20 drift) target kills them',()=>{const f=fixture(6);try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const interrogator=f.manager.players(f.code).find(p=>p.role_id==='interrogator'),target=f.manager.players(f.code).find(p=>p.player_code!==interrogator.player_code&&p.faction==='loyalist');f.manager.db.prepare('UPDATE hr_players SET drift=20 WHERE game_code=? AND player_code=?').run(f.code,target.player_code);f.manager.submitAction(f.code,interrogator.player_code,{targetCode:target.player_code,variant:'T2'});f.manager.resolve(f.code,true);const after=f.manager.player(f.code,target.player_code);assert.equal(after.alive,0,'Black zone (drift 20) is >=2 zone-upgrade, same threshold as Red — executes on T2+');assert.equal(after.drift,20,'drift is untouched by the execution itself');}finally{f.close();}});

test('Execute on Sight — a T1 (Soft) scan never kills, even against a Black-zone target',()=>{const f=fixture(6);try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const interrogator=f.manager.players(f.code).find(p=>p.role_id==='interrogator'),target=f.manager.players(f.code).find(p=>p.player_code!==interrogator.player_code&&p.faction==='loyalist');f.manager.db.prepare('UPDATE hr_players SET drift=20 WHERE game_code=? AND player_code=?').run(f.code,target.player_code);f.manager.submitAction(f.code,interrogator.player_code,{targetCode:target.player_code,variant:'T1'});f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,target.player_code).alive,1,'T1 is the soft probe tier — execute-on-sight requires T2+ regardless of target zone');}finally{f.close();}});

test('T1 (Soft) scan result names the actual target, not a generic "Target"',()=>{const f=fixture(6);try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const interrogator=f.manager.players(f.code).find(p=>p.role_id==='interrogator'),target=f.manager.players(f.code).find(p=>p.player_code!==interrogator.player_code&&p.faction==='loyalist');f.manager.submitAction(f.code,interrogator.player_code,{targetCode:target.player_code,variant:'T1'});f.manager.resolve(f.code,true);const msgs=f.manager.db.prepare("SELECT body FROM hr_messages WHERE game_code=? AND channel='private' AND recipient_code=?").all(f.code,interrogator.player_code);assert.ok(msgs.some(m=>m.body===`${target.name} is clean.`||m.body===`${target.name} is tainted.`),'result names the target by name, e.g. "P1 is clean."');assert.ok(!msgs.some(m=>/^Target:/.test(m.body)),'no generic "Target:" phrasing left');}finally{f.close();}});

