test('L7: T2 crippled Psyker permanently blocked — T2 does not recover',()=>{const f=fixture(7);try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const psyker=f.manager.players(f.code).find(p=>p.role_id==='sanctioned-psyker'),target=f.manager.players(f.code).find(p=>p.faction==='heretic');f.manager.db.prepare('UPDATE hr_players SET cripple_tier=2 WHERE game_code=? AND player_code=?').run(f.code,psyker.player_code);assert.throws(()=>f.manager.submitAction(f.code,psyker.player_code,{targetCode:target.player_code}),/blocks this action/);f.manager.advance(f.code,'p0');f.manager.advance(f.code,'p0');assert.equal(f.manager.player(f.code,psyker.player_code).cripple_tier,2,'T2 persists');f.manager.db.prepare("UPDATE hr_games SET phase='night',round=2 WHERE code=?").run(f.code);assert.throws(()=>f.manager.submitAction(f.code,psyker.player_code,{targetCode:target.player_code}),/blocks this action/);}finally{f.close();}});

test('L7: killLimit honored — Psyker cannot fire a second time',()=>{const f=fixture(7);try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const psyker=f.manager.players(f.code).find(p=>p.role_id==='sanctioned-psyker'),target1=f.manager.players(f.code).find(p=>p.faction==='heretic');f.manager.submitAction(f.code,psyker.player_code,{targetCode:target1.player_code});f.manager.resolve(f.code,true);assert.equal(f.manager.usage(f.code,psyker.player_code,'kill'),1,'first kill consumed');const target2=f.manager.players(f.code).find(p=>p.alive&&p.faction==='heretic'&&p.player_code!==target1.player_code);f.manager.db.prepare("UPDATE hr_games SET phase='night',round=2 WHERE code=?").run(f.code);assert.throws(()=>f.manager.submitAction(f.code,psyker.player_code,{targetCode:target2.player_code}),/once per game/);}finally{f.close();}});

