function fixtureHereticPriest(count=8){const dir=fs.mkdtempSync(path.join(os.tmpdir(),'heresy-hp-'));let now=1_000_000;const manager=new HeresyGameManager({databasePath:path.join(dir,'game.db'),now:()=>now,random:()=>0.9});const{code}=manager.create({playerCode:'p0',name:'P0'});for(let i=1;i<count;i++){manager.join({code,playerCode:`p${i}`,name:`P${i}`});manager.ready(code,`p${i}`,true);}return{manager,code,close(){manager.close();fs.rmSync(dir,{recursive:true,force:true});}};}

function setupHereticPriestGame(f){f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const players=f.manager.players(f.code);const hp=players.find(p=>p.role_id==='heretic-priest');if(!hp){const p=players.find(x=>x.faction==='heretic');f.manager.db.prepare('UPDATE hr_players SET role_id=?,faction=? WHERE game_code=? AND player_code=?').run('heretic-priest','heretic',f.code,p.player_code);}const priest=f.manager.players(f.code).find(p=>p.role_id==='heretic-priest');const target=f.manager.players(f.code).find(p=>p.player_code!==priest.player_code);return{priest,target};}

test('H2: Warp Litany against Green-zone target (drift 0) silently rejects',()=>{const f=fixtureHereticPriest();try{const{priest,target}=setupHereticPriestGame(f);f.manager.db.prepare('UPDATE hr_players SET drift=0,skip_next_night=1 WHERE game_code=? AND player_code=?').run(f.code,target.player_code);const result=f.manager.submitAction(f.code,priest.player_code,{targetCode:target.player_code,variant:'warp-litany'});assert.equal(result.silent,true,'action silently rejected');assert.equal(result.ok,false,'ok is false');f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,priest.player_code).drift,0,'priest drift unchanged');assert.equal(f.manager.player(f.code,target.player_code).drift,0,'target drift unchanged');const privateMsgs=f.manager.db.prepare("SELECT * FROM hr_messages WHERE game_code=? AND channel='private' AND recipient_code IN (?,?)").all(f.code,priest.player_code,target.player_code);assert.ok(!privateMsgs.some(m=>/warp|litany/i.test(m.body)),'no notification to either party');const actions=f.manager.actions(f.code,f.manager.game(f.code).round);assert.equal(actions.length,0,'no action recorded');}finally{f.close();}});

test('H2: Warp Litany against Yellow-zone target (drift 9) silently rejects',()=>{const f=fixtureHereticPriest();try{const{priest,target}=setupHereticPriestGame(f);f.manager.db.prepare('UPDATE hr_players SET drift=9,skip_next_night=1 WHERE game_code=? AND player_code=?').run(f.code,target.player_code);const result=f.manager.submitAction(f.code,priest.player_code,{targetCode:target.player_code,variant:'warp-litany'});assert.equal(result.silent,true,'action silently rejected');assert.equal(result.ok,false,'ok is false');f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,priest.player_code).drift,0,'priest drift unchanged');assert.equal(f.manager.player(f.code,target.player_code).drift,9,'target drift unchanged');const actions=f.manager.actions(f.code,f.manager.game(f.code).round);assert.equal(actions.length,0,'no action recorded');}finally{f.close();}});

test('H2: Warp Litany against Orange-zone target (drift 10) succeeds',()=>{const f=fixtureHereticPriest();try{const{priest,target}=setupHereticPriestGame(f);f.manager.db.prepare('UPDATE hr_players SET drift=10,skip_next_night=1 WHERE game_code=? AND player_code=?').run(f.code,target.player_code);const result=f.manager.submitAction(f.code,priest.player_code,{targetCode:target.player_code,variant:'warp-litany'});assert.equal(result.silent,undefined,'action not silently rejected');assert.equal(result.kind,'corrupt-sermon');f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,priest.player_code).drift,4,'priest gains +4 drift');assert.equal(f.manager.player(f.code,target.player_code).drift,20,'target gains +12 drift (capped at max 20)');const usage=f.manager.usage(f.code,priest.player_code,'warp-litany');assert.equal(usage,1,'warp litany usage incremented');}finally{f.close();}});

test('H2: Warp Litany against Red-zone target (drift 15) succeeds',()=>{const f=fixtureHereticPriest();try{const{priest,target}=setupHereticPriestGame(f);f.manager.db.prepare('UPDATE hr_players SET drift=15,skip_next_night=1 WHERE game_code=? AND player_code=?').run(f.code,target.player_code);const result=f.manager.submitAction(f.code,priest.player_code,{targetCode:target.player_code,variant:'warp-litany'});assert.equal(result.silent,undefined,'action not silently rejected');f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,priest.player_code).drift,4,'priest gains +4 drift');assert.equal(f.manager.player(f.code,target.player_code).drift,20,'target gains +12 drift (capped at max)');}finally{f.close();}});

test('H2: Warp Litany once-per-game enforced — silent reject does not consume the usage',()=>{const f=fixtureHereticPriest();try{const{priest,target}=setupHereticPriestGame(f);f.manager.db.prepare('UPDATE hr_players SET drift=0 WHERE game_code=? AND player_code=?').run(f.code,target.player_code);const result1=f.manager.submitAction(f.code,priest.player_code,{targetCode:target.player_code,variant:'warp-litany'});assert.equal(result1.silent,true,'first attempt silently rejected');assert.equal(result1.ok,false);f.manager.resolve(f.code,true);f.manager.db.prepare("UPDATE hr_games SET phase='night',round=2 WHERE code=?").run(f.code);f.manager.db.prepare('UPDATE hr_players SET drift=10,skip_next_night=1 WHERE game_code=? AND player_code=?').run(f.code,target.player_code);const result2=f.manager.submitAction(f.code,priest.player_code,{targetCode:target.player_code,variant:'warp-litany'});assert.equal(result2.silent,undefined,'second attempt succeeds');f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,priest.player_code).drift,4,'priest gains +4 drift on successful use');const usage=f.manager.usage(f.code,priest.player_code,'warp-litany');assert.equal(usage,1,'usage count is 1 after successful use');f.manager.db.prepare("UPDATE hr_games SET phase='night',round=3 WHERE code=?").run(f.code);assert.throws(()=>f.manager.submitAction(f.code,priest.player_code,{targetCode:target.player_code,variant:'warp-litany'}),/limit/,'third attempt throws limit error');}finally{f.close();}});

// ── H1: Murderer drift-gated kill (heretic-kit.md v1.5.0) ──
// NOTE: the dispatch's own test table includes "Murderer at drift 5 (Yellow)
// attempts kill -> Gated" but 5+15=20 is NOT >MAX_DRIFT(20) per the gate's
// own stated formula (both docs agree: "if current_drift+15 > MAX_DRIFT").
// That example doesn't gate under the formula as written — using drift 6
// (21>20) here instead, which is the correct lowest-Yellow gating value.

test('H1: Murderer kills at drift 0 → succeeds, +16 drift (15 kill + 1 witness), target dies',()=>{const f=fixture(5);try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const murderer=f.manager.players(f.code).find(p=>p.role_id==='murderer'),target=f.manager.players(f.code).find(p=>p.faction==='loyalist'&&p.player_code!==murderer.player_code);f.manager.submitAction(f.code,murderer.player_code,{targetCode:target.player_code});f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,target.player_code).alive,0,'target died');assert.equal(f.manager.player(f.code,murderer.player_code).drift,16,'Murderer at +16 (15 kill + 1 witness)');}finally{f.close();}});

test('H1: Murderer at drift 15 (Red) is gated — no drift charged, target +1, Red cue',()=>{const f=fixture(5);try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const murderer=f.manager.players(f.code).find(p=>p.role_id==='murderer'),target=f.manager.players(f.code).find(p=>p.faction==='loyalist'&&p.player_code!==murderer.player_code);f.manager.db.prepare('UPDATE hr_players SET drift=15 WHERE game_code=? AND player_code=?').run(f.code,murderer.player_code);f.manager.submitAction(f.code,murderer.player_code,{targetCode:target.player_code});f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,murderer.player_code).drift,15,'Murderer unchanged');assert.equal(f.manager.player(f.code,target.player_code).alive,1,'target survived');assert.equal(f.manager.player(f.code,target.player_code).drift,1,'target felt watched (+1)');const state=f.manager.state(f.code,murderer.player_code);assert.match(state.privateMessages.at(-1).body,/Warp peels away your intent/,'Red-tone cue delivered privately');const event=f.manager.db.prepare("SELECT payload FROM hr_events WHERE game_code=? AND type='night-action' ORDER BY id DESC LIMIT 1").get(f.code);assert.equal(JSON.parse(event.payload).kind,'murderer:kill-gated');}finally{f.close();}});

test('H1: Murderer at drift 6 (Yellow, lowest gating value) is gated — Yellow-tone cue',()=>{const f=fixture(5);try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const murderer=f.manager.players(f.code).find(p=>p.role_id==='murderer'),target=f.manager.players(f.code).find(p=>p.faction==='loyalist'&&p.player_code!==murderer.player_code);f.manager.db.prepare('UPDATE hr_players SET drift=6 WHERE game_code=? AND player_code=?').run(f.code,murderer.player_code);f.manager.submitAction(f.code,murderer.player_code,{targetCode:target.player_code});f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,murderer.player_code).drift,6,'gated — unchanged');const state=f.manager.state(f.code,murderer.player_code);assert.match(state.privateMessages.at(-1).body,/hesitation, a wrongness/,'Yellow-tone cue');}finally{f.close();}});

test('H1: Murderer at drift 13 (Orange) is gated — Orange-tone cue',()=>{const f=fixture(5);try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const murderer=f.manager.players(f.code).find(p=>p.role_id==='murderer'),target=f.manager.players(f.code).find(p=>p.faction==='loyalist'&&p.player_code!==murderer.player_code);f.manager.db.prepare('UPDATE hr_players SET drift=13 WHERE game_code=? AND player_code=?').run(f.code,murderer.player_code);f.manager.submitAction(f.code,murderer.player_code,{targetCode:target.player_code});f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,murderer.player_code).drift,13,'gated — unchanged');const state=f.manager.state(f.code,murderer.player_code);assert.match(state.privateMessages.at(-1).body,/hand is shaking/,'Orange-tone cue');}finally{f.close();}});

test('H1: gate fires before interrupts are evaluated — Chirurgeon protect not even reached',()=>{const f=fixture(5);try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const murderer=f.manager.players(f.code).find(p=>p.role_id==='murderer'),chirurgeon=f.manager.players(f.code).find(p=>p.role_id==='chirurgeon'),target=f.manager.players(f.code).find(p=>p.faction==='loyalist'&&p.player_code!==murderer.player_code&&p.player_code!==chirurgeon.player_code);f.manager.db.prepare('UPDATE hr_players SET drift=19 WHERE game_code=? AND player_code=?').run(f.code,murderer.player_code);f.manager.submitAction(f.code,chirurgeon.player_code,{targetCode:target.player_code});f.manager.submitAction(f.code,murderer.player_code,{targetCode:target.player_code});f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,murderer.player_code).drift,19,'unchanged — gated (19+15=34>20)');assert.equal(f.manager.player(f.code,target.player_code).drift,1,'target only gets the gate tick, protect never evaluated');}finally{f.close();}});

test('H1: Priest Litany heals Murderer below the gate, enabling a later kill',()=>{const f=fixture(5);try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const murderer=f.manager.players(f.code).find(p=>p.role_id==='murderer'),priest=f.manager.players(f.code).find(p=>p.role_id==='priest'),target=f.manager.players(f.code).find(p=>p.faction==='loyalist'&&p.player_code!==murderer.player_code);f.manager.db.prepare('UPDATE hr_players SET drift=7 WHERE game_code=? AND player_code=?').run(f.code,murderer.player_code);f.manager.submitAction(f.code,priest.player_code,{targetCode:murderer.player_code,variant:'litany'});f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,murderer.player_code).drift,0,'Litany floored at 0 (7-10)');f.manager.db.prepare("UPDATE hr_games SET phase='night' WHERE code=?").run(f.code);f.manager.submitAction(f.code,murderer.player_code,{targetCode:target.player_code});f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,target.player_code).alive,0,'kill succeeds from drift 0');assert.equal(f.manager.player(f.code,murderer.player_code).drift,16,'Murderer at +16 (15 kill + 1 witness)');}finally{f.close();}});

// ── Blood Ritual (blood-ritual.md v1.0.0), formerly "Sanctioned Violence" ──
// Renamed 2026-07-25 — "Sanctioned" read as a Loyalist-flavored word for a
// Heretic mechanic. Murderer is a valid attacker (reversed from the initial
// dispatch read); note they still only get one action per night — a kill and
// a Blood Ritual submission share the same hr_actions row, so taking one
// forgoes the other that night (see submitFactionAction's comment). No
// alignment reveal on kill, matching the spec's explicit "same as Murderer"
// statement (not the contradictory action-shape-table row implying a reveal).

test('Blood Ritual: fresh attack cripples the target one tier, no witness drift',()=>{const f=fixture(8);try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const saboteur=f.manager.players(f.code).find(p=>p.role_id==='saboteur'),target=f.manager.players(f.code).find(p=>p.faction==='loyalist');f.manager.submitFactionAction(f.code,saboteur.player_code,{targetCode:target.player_code});f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,saboteur.player_code).drift,3,'attacker paid +3');assert.equal(f.manager.player(f.code,target.player_code).cripple_tier,1,'target crippled +1 tier');assert.equal(f.manager.player(f.code,target.player_code).alive,1,'target survives night 1');assert.ok(f.manager.players(f.code).filter(p=>p.alive&&p.player_code!==saboteur.player_code).every(p=>p.drift===0),'no witness drift on a cripple night');}finally{f.close();}});

test('Blood Ritual: same target attacked the following night escalates to a kill',()=>{const f=fixture(8);try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const saboteur=f.manager.players(f.code).find(p=>p.role_id==='saboteur'),target=f.manager.players(f.code).find(p=>p.faction==='loyalist');f.manager.submitFactionAction(f.code,saboteur.player_code,{targetCode:target.player_code});f.manager.resolve(f.code,true);f.manager.db.prepare("UPDATE hr_games SET phase='night' WHERE code=?").run(f.code);f.manager.submitFactionAction(f.code,saboteur.player_code,{targetCode:target.player_code});f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,target.player_code).alive,0,'target killed on the escalation night');assert.equal(f.manager.player(f.code,target.player_code).cripple_tier,3,'tier at MAX');assert.equal(f.manager.player(f.code,saboteur.player_code).drift,7,'3+3 attacker cost + 1 witness');const msgs=f.manager.historyMessages(f.code,'p0','public').messages;assert.ok(!msgs.some(m=>new RegExp(target.name+'.*(loyalist|heretic)').test(m.body)),'no alignment reveal on an SV kill');}finally{f.close();}});

test('Blood Ritual: different target the following night resets escalation (fresh cripple, no kill)',()=>{const f=fixture(8);try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const saboteur=f.manager.players(f.code).find(p=>p.role_id==='saboteur'),targets=f.manager.players(f.code).filter(p=>p.faction==='loyalist');f.manager.submitFactionAction(f.code,saboteur.player_code,{targetCode:targets[0].player_code});f.manager.resolve(f.code,true);f.manager.db.prepare("UPDATE hr_games SET phase='night' WHERE code=?").run(f.code);f.manager.submitFactionAction(f.code,saboteur.player_code,{targetCode:targets[1].player_code});f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,targets[1].player_code).cripple_tier,1,'fresh cripple, not escalated');assert.equal(f.manager.player(f.code,targets[1].player_code).alive,1);}finally{f.close();}});

test('Blood Ritual: skipping a night resets escalation — next attack on the same target is a fresh cripple',()=>{const f=fixture(8);try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const saboteur=f.manager.players(f.code).find(p=>p.role_id==='saboteur'),target=f.manager.players(f.code).find(p=>p.faction==='loyalist');f.manager.submitFactionAction(f.code,saboteur.player_code,{targetCode:target.player_code});f.manager.resolve(f.code,true);f.manager.db.prepare("UPDATE hr_games SET phase='night' WHERE code=?").run(f.code);f.manager.resolve(f.code,true);f.manager.db.prepare("UPDATE hr_games SET phase='night' WHERE code=?").run(f.code);f.manager.submitFactionAction(f.code,saboteur.player_code,{targetCode:target.player_code});f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,target.player_code).alive,1,'streak was broken by the skip — no kill');
  // Not tier 2: the skipped night gave the pre-existing T1-recovery rule (in
  // setPhase) a full cycle to heal the round-1 cripple back to 0 before this
  // fresh cripple landed — so it's a fresh 0->1, not a stacked 1->2.
  assert.equal(f.manager.player(f.code,target.player_code).cripple_tier,1,'fresh cripple from a healed baseline (0->1), not jumped to 3');}finally{f.close();}});

test('Blood Ritual: a second faction-wide submission the same night is rejected outright',()=>{const f=fixture(8);try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const saboteur=f.manager.players(f.code).find(p=>p.role_id==='saboteur'),hereticPriest=f.manager.players(f.code).find(p=>p.role_id==='heretic-priest'),targets=f.manager.players(f.code).filter(p=>p.faction==='loyalist');f.manager.submitFactionAction(f.code,saboteur.player_code,{targetCode:targets[0].player_code});assert.throws(()=>f.manager.submitFactionAction(f.code,hereticPriest.player_code,{targetCode:targets[1].player_code}),/already been claimed/);}finally{f.close();}});

test('Blood Ritual: a crippled Heretic cannot submit Blood Ritual',()=>{const f=fixture(8);try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const saboteur=f.manager.players(f.code).find(p=>p.role_id==='saboteur'),target=f.manager.players(f.code).find(p=>p.faction==='loyalist');f.manager.db.prepare('UPDATE hr_players SET cripple_tier=2 WHERE game_code=? AND player_code=?').run(f.code,saboteur.player_code);assert.throws(()=>f.manager.submitFactionAction(f.code,saboteur.player_code,{targetCode:target.player_code}),/Interrogation damage blocks/);}finally{f.close();}});

test('Blood Ritual: targeting a fellow Heretic is rejected',()=>{const f=fixture(8);try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const saboteur=f.manager.players(f.code).find(p=>p.role_id==='saboteur'),fellowHeretic=f.manager.players(f.code).find(p=>p.faction==='heretic'&&p.player_code!==saboteur.player_code);assert.throws(()=>f.manager.submitFactionAction(f.code,saboteur.player_code,{targetCode:fellowHeretic.player_code}),/not hostile/);}finally{f.close();}});

test('Blood Ritual: the Murderer is a valid attacker for the cabal',()=>{const f=fixture(8);try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const murderer=f.manager.players(f.code).find(p=>p.role_id==='murderer'),target=f.manager.players(f.code).find(p=>p.faction==='loyalist');f.manager.submitFactionAction(f.code,murderer.player_code,{targetCode:target.player_code});f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,murderer.player_code).drift,3,'Murderer paid the Blood Ritual attacker cost, not the +15 kill cost');assert.equal(f.manager.player(f.code,target.player_code).cripple_tier,1,'fresh cripple landed');}finally{f.close();}});

test('Blood Ritual: a Murderer who submits it that night forgoes their own kill (shared action slot)',()=>{const f=fixture(5);try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const murderer=f.manager.players(f.code).find(p=>p.role_id==='murderer'),target=f.manager.players(f.code).find(p=>p.faction==='loyalist'&&p.player_code!==murderer.player_code);f.manager.submitAction(f.code,murderer.player_code,{targetCode:target.player_code});f.manager.submitFactionAction(f.code,murderer.player_code,{targetCode:target.player_code});f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,murderer.player_code).drift,3,'only the Blood Ritual cost applied — the kill submission was overwritten');assert.equal(f.manager.player(f.code,target.player_code).alive,1,'no kill happened, only a cripple');assert.equal(f.manager.player(f.code,target.player_code).cripple_tier,1);}finally{f.close();}});

test('Blood Ritual: a Loyalist cannot submit Blood Ritual',()=>{const f=fixture(8);try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const loyalist=f.manager.players(f.code).find(p=>p.faction==='loyalist'),target=f.manager.players(f.code).find(p=>p.faction==='loyalist'&&p.player_code!==loyalist.player_code);assert.throws(()=>f.manager.submitFactionAction(f.code,loyalist.player_code,{targetCode:target.player_code}),/Only Heretics/);}finally{f.close();}});

test('Blood Ritual: Chirurgeon protect blocks the attack silently, attacker still pays',()=>{const f=fixture(8);try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const saboteur=f.manager.players(f.code).find(p=>p.role_id==='saboteur'),chirurgeon=f.manager.players(f.code).find(p=>p.role_id==='chirurgeon'),target=f.manager.players(f.code).find(p=>p.faction==='loyalist'&&p.player_code!==chirurgeon.player_code);f.manager.submitAction(f.code,chirurgeon.player_code,{targetCode:target.player_code});f.manager.submitFactionAction(f.code,saboteur.player_code,{targetCode:target.player_code});f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,target.player_code).cripple_tier,0,'protected — no cripple landed');assert.equal(f.manager.player(f.code,saboteur.player_code).drift,3,'attacker still paid the cost');}finally{f.close();}});

test('Blood Ritual: Saboteur trap on the attack target adds +5 extra drift to the attacker',()=>{const f=fixture(8);try{f.manager.start(f.code,'p0');f.manager.advance(f.code,'p0');const hereticPriest=f.manager.players(f.code).find(p=>p.role_id==='heretic-priest'),saboteur=f.manager.players(f.code).find(p=>p.role_id==='saboteur'),target=f.manager.players(f.code).find(p=>p.faction==='loyalist');f.manager.submitAction(f.code,saboteur.player_code,{targetCode:target.player_code});f.manager.submitFactionAction(f.code,hereticPriest.player_code,{targetCode:target.player_code});f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,hereticPriest.player_code).drift,8,'3 attacker cost + 5 trap');assert.equal(f.manager.player(f.code,target.player_code).cripple_tier,1,'cripple still lands despite the trap-on-target');}finally{f.close();}});

// ── Animus (roles/animus.md v1.0.0) — one-shot speculative possession ──
// Animus ships custom-roster only (not in any locked preset), so every test
// below starts from fixture(8) and reassigns a loyalist slot to animus/heretic
// directly, matching the arbitrator-reassignment pattern used above (L5).

// Composition is assigned inside start(), so the role_id/faction swap must
// happen AFTER start() runs — reassigning before it gets clobbered.
// Convert an EXISTING Heretic (not the Murderer) to Animus, not a Loyalist —
// swapping a Loyalist's faction would shift the heretic/loyalist ratio and
// can trip the parity win check the instant start() finishes.
function makeAnimus(f){const candidate=f.manager.players(f.code).find(p=>p.faction==='heretic'&&p.role_id!=='murderer');f.manager.db.prepare('UPDATE hr_players SET role_id=?,faction=? WHERE game_code=? AND player_code=?').run('animus','heretic',f.code,candidate.player_code);return f.manager.player(f.code,candidate.player_code);}

test('Animus: a Red-zone guess (15-19) succeeds — target possessed, skips next night, no reveal yet',()=>{const f=fixture(8);try{f.manager.start(f.code,'p0');makeAnimus(f);f.manager.advance(f.code,'p0');const animus=f.manager.players(f.code).find(p=>p.role_id==='animus'),target=f.manager.players(f.code).find(p=>p.faction==='loyalist');f.manager.db.prepare('UPDATE hr_players SET drift=17 WHERE game_code=? AND player_code=?').run(f.code,target.player_code);f.manager.submitAction(f.code,animus.player_code,{targetCode:target.player_code});f.manager.resolve(f.code,true);const after=f.manager.player(f.code,target.player_code);assert.equal(after.possessed_by,animus.player_code,'target is possessed');assert.equal(after.skip_next_night,1,'target skips their next night action');assert.equal(after.alive,1,'no kill yet — detonation is day-end, not night-end');assert.equal(after.possession_revealed,0,'not yet revealed');const state=f.manager.state(f.code,animus.player_code);assert.match(state.privateMessages.at(-1).body,/summoning takes hold/);}finally{f.close();}});

test('Animus: a wrong guess (outside Red) wastes silently — no possession, no error, no learned reason',()=>{const f=fixture(8);try{f.manager.start(f.code,'p0');makeAnimus(f);f.manager.advance(f.code,'p0');const animus=f.manager.players(f.code).find(p=>p.role_id==='animus'),target=f.manager.players(f.code).find(p=>p.faction==='loyalist');f.manager.db.prepare('UPDATE hr_players SET drift=5 WHERE game_code=? AND player_code=?').run(f.code,target.player_code);f.manager.submitAction(f.code,animus.player_code,{targetCode:target.player_code});f.manager.resolve(f.code,true);const after=f.manager.player(f.code,target.player_code);assert.equal(after.possessed_by,null,'not possessed');assert.equal(after.skip_next_night,0);const state=f.manager.state(f.code,animus.player_code);assert.match(state.privateMessages.at(-1).body,/finds no purchase/);}finally{f.close();}});

test('Animus: Chirurgeon protecting a Red-zone target the same night blocks the possession itself, indistinguishable from a wrong guess',()=>{const f=fixture(8);try{f.manager.start(f.code,'p0');makeAnimus(f);f.manager.advance(f.code,'p0');const animus=f.manager.players(f.code).find(p=>p.role_id==='animus'),chirurgeon=f.manager.players(f.code).find(p=>p.role_id==='chirurgeon'),target=f.manager.players(f.code).find(p=>p.faction==='loyalist'&&p.role_id!=='chirurgeon');f.manager.db.prepare('UPDATE hr_players SET drift=17 WHERE game_code=? AND player_code=?').run(f.code,target.player_code);f.manager.submitAction(f.code,chirurgeon.player_code,{targetCode:target.player_code});f.manager.submitAction(f.code,animus.player_code,{targetCode:target.player_code});f.manager.resolve(f.code,true);const after=f.manager.player(f.code,target.player_code);assert.equal(after.possessed_by,null,'possession was blocked despite the target actually being Red');assert.equal(after.skip_next_night,0);const state=f.manager.state(f.code,animus.player_code);assert.match(state.privateMessages.at(-1).body,/finds no purchase/,'Animus sees the same failure message as a wrong guess, no tell that it was blocked');assert.equal(f.manager.player(f.code,animus.player_code).drift,3,'Animus still pays the +3 attempt cost even though the possession was blocked');}finally{f.close();}});

test('Animus: self-drift is charged exactly once, at submission, win or lose (no double-charge)',()=>{const f=fixture(8);try{f.manager.start(f.code,'p0');makeAnimus(f);f.manager.advance(f.code,'p0');const animus=f.manager.players(f.code).find(p=>p.role_id==='animus'),target=f.manager.players(f.code).find(p=>p.faction==='loyalist');f.manager.db.prepare('UPDATE hr_players SET drift=5 WHERE game_code=? AND player_code=?').run(f.code,target.player_code);f.manager.submitAction(f.code,animus.player_code,{targetCode:target.player_code});assert.equal(f.manager.player(f.code,animus.player_code).drift,3,'charged immediately on submission');f.manager.resolve(f.code,true);assert.equal(f.manager.player(f.code,animus.player_code).drift,3,'unchanged by resolution — not double-charged by the generic per-player loop');}finally{f.close();}});

test('Animus: targeting a fellow Heretic is rejected (faction-locked)',()=>{const f=fixture(8);try{f.manager.start(f.code,'p0');makeAnimus(f);f.manager.advance(f.code,'p0');const animus=f.manager.players(f.code).find(p=>p.role_id==='animus'),fellowHeretic=f.manager.players(f.code).find(p=>p.faction==='heretic'&&p.player_code!==animus.player_code);assert.throws(()=>f.manager.submitAction(f.code,animus.player_code,{targetCode:fellowHeretic.player_code}),/not hostile/);}finally{f.close();}});

test('Animus: a dead target is rejected outright',()=>{const f=fixture(8);try{f.manager.start(f.code,'p0');makeAnimus(f);f.manager.advance(f.code,'p0');const animus=f.manager.players(f.code).find(p=>p.role_id==='animus'),target=f.manager.players(f.code).find(p=>p.faction==='loyalist');f.manager.db.prepare('UPDATE hr_players SET alive=0 WHERE game_code=? AND player_code=?').run(f.code,target.player_code);assert.throws(()=>f.manager.submitAction(f.code,animus.player_code,{targetCode:target.player_code}),/Dead players cannot do that/);}finally{f.close();}});

test('Animus: an already-possessed target cannot be targeted again',()=>{const f=fixture(9);try{f.manager.start(f.code,'p0');makeAnimus(f);f.manager.advance(f.code,'p0');const animus=f.manager.players(f.code).find(p=>p.role_id==='animus'),target=f.manager.players(f.code).find(p=>p.faction==='loyalist');f.manager.db.prepare('UPDATE hr_players SET possessed_by=? WHERE game_code=? AND player_code=?').run('someone-else',f.code,target.player_code);assert.throws(()=>f.manager.submitAction(f.code,animus.player_code,{targetCode:target.player_code}),/already possessed/);}finally{f.close();}});

test('Animus: one-shot — a second attempt after a resolved possession is rejected',()=>{const f=fixture(8);try{f.manager.start(f.code,'p0');makeAnimus(f);f.manager.advance(f.code,'p0');const animus=f.manager.players(f.code).find(p=>p.role_id==='animus'),targets=f.manager.players(f.code).filter(p=>p.faction==='loyalist');f.manager.db.prepare('UPDATE hr_players SET drift=17 WHERE game_code=? AND player_code=?').run(f.code,targets[0].player_code);f.manager.submitAction(f.code,animus.player_code,{targetCode:targets[0].player_code});f.manager.resolve(f.code,true);f.manager.db.prepare("UPDATE hr_games SET phase='night' WHERE code=?").run(f.code);assert.throws(()=>f.manager.submitAction(f.code,animus.player_code,{targetCode:targets[1].player_code}),/one possession per game/);}finally{f.close();}});

test('Animus: possessed player\'s vote is silently suppressed from the tally',()=>{const f=fixture(9);try{f.manager.start(f.code,'p0');makeAnimus(f);f.manager.advance(f.code,'p0');const animus=f.manager.players(f.code).find(p=>p.role_id==='animus'),possessed=f.manager.players(f.code).find(p=>p.faction==='loyalist'),lynchTarget=f.manager.players(f.code).find(p=>p.faction==='loyalist'&&p.player_code!==possessed.player_code);f.manager.db.prepare('UPDATE hr_players SET possessed_by=? WHERE game_code=? AND player_code=?').run(animus.player_code,f.code,possessed.player_code);f.manager.db.prepare("UPDATE hr_games SET phase='day',round=2,day_stage='vote' WHERE code=?").run(f.code);const others=f.manager.players(f.code).filter(p=>p.player_code!==possessed.player_code&&p.player_code!==lynchTarget.player_code&&p.alive);// Cast the possessed player's own vote for someone who should NOT win the tally if it counted
f.manager.vote(f.code,possessed.player_code,others[0].player_code);for(const p of others)f.manager.vote(f.code,p.player_code,lynchTarget.player_code);f.manager.resolve(f.code,true);const event=JSON.parse(f.manager.db.prepare("SELECT payload FROM hr_events WHERE game_code=? AND type='day-resolution' ORDER BY id DESC LIMIT 1").get(f.code).payload);assert.equal(event.target,lynchTarget.player_code,'possessed vote for the other candidate never counted');assert.equal(event.voterResults.some(r=>r.voter===possessed.player_code),false,'possessed voter excluded entirely from the tally');}finally{f.close();}});

test('Animus: day-end detonation kills the possessed target, reveals full role/faction/drift to everyone, excludes Animus from witness drift',()=>{const f=fixture(9);try{f.manager.start(f.code,'p0');makeAnimus(f);f.manager.advance(f.code,'p0');const animus=f.manager.players(f.code).find(p=>p.role_id==='animus'),target=f.manager.players(f.code).find(p=>p.faction==='loyalist');f.manager.db.prepare('UPDATE hr_players SET possessed_by=? WHERE game_code=? AND player_code=?').run(animus.player_code,f.code,target.player_code);f.manager.db.prepare("UPDATE hr_games SET phase='day',round=2,day_stage='vote' WHERE code=?").run(f.code);const voters=f.manager.players(f.code).filter(p=>p.player_code!==target.player_code&&p.alive).slice(0,3);for(const p of voters)f.manager.vote(f.code,p.player_code,'skip');f.manager.resolve(f.code,true);const after=f.manager.player(f.code,target.player_code);assert.equal(after.alive,0,'detonated');assert.equal(after.possession_revealed,1);assert.equal(after.drift,0);const bystander=f.manager.players(f.code).find(p=>p.player_code!==animus.player_code&&p.player_code!==target.player_code);const bystanderState=f.manager.state(f.code,bystander.player_code);const revealed=bystanderState.players.find(p=>p.playerCode===target.player_code);assert.ok(revealed.role,'role revealed to a third party');assert.equal(revealed.faction,'loyalist');assert.equal(revealed.possessed,true);assert.equal(f.manager.player(f.code,bystander.player_code).drift,1,'bystander gets witnessed-violence drift');assert.equal(f.manager.player(f.code,animus.player_code).drift,0,'Animus itself is excluded from witnessed-violence drift');const events=f.manager.db.prepare("SELECT payload FROM hr_events WHERE game_code=? AND type='drift' ORDER BY id DESC LIMIT 5").all(f.code).map(e=>JSON.parse(e.payload));assert.equal(events.some(e=>e.playerCode===animus.player_code&&e.reason==='witnessed-violence'),false);}finally{f.close();}});

test('Animus: E1 — target lynched the same day the possession resolves still gets the fuller Neverborn reveal',()=>{const f=fixture(9);try{f.manager.start(f.code,'p0');makeAnimus(f);f.manager.advance(f.code,'p0');const animus=f.manager.players(f.code).find(p=>p.role_id==='animus'),target=f.manager.players(f.code).find(p=>p.faction==='loyalist');f.manager.db.prepare('UPDATE hr_players SET possessed_by=? WHERE game_code=? AND player_code=?').run(animus.player_code,f.code,target.player_code);f.manager.db.prepare("UPDATE hr_games SET phase='day',round=2,day_stage='vote' WHERE code=?").run(f.code);const voters=f.manager.players(f.code).filter(p=>p.player_code!==target.player_code&&p.alive).slice(0,3);for(const p of voters)f.manager.vote(f.code,p.player_code,target.player_code);f.manager.resolve(f.code,true);const after=f.manager.player(f.code,target.player_code);assert.equal(after.alive,0,'lynched');assert.equal(after.possession_revealed,1,'detonation still ran on the already-dead body');const msgs=f.manager.historyMessages(f.code,'p0','public').messages;assert.ok(msgs.some(m=>/body ruptures/.test(m.body)),'the fuller Neverborn reveal fired despite the lynch already killing the target');}finally{f.close();}});

test('Animus: possessed player cannot speak in public chat, but can speak-as the possessed target via sendMessageAs',()=>{const f=fixture(9);try{f.manager.start(f.code,'p0');makeAnimus(f);f.manager.advance(f.code,'p0');const animus=f.manager.players(f.code).find(p=>p.role_id==='animus'),target=f.manager.players(f.code).find(p=>p.faction==='loyalist');f.manager.db.prepare('UPDATE hr_players SET possessed_by=? WHERE game_code=? AND player_code=?').run(animus.player_code,f.code,target.player_code);f.manager.db.prepare("UPDATE hr_games SET phase='day',round=2,day_stage='vote' WHERE code=?").run(f.code);assert.throws(()=>f.manager.sendMessage(f.code,target.player_code,'public','I am innocent'),/possessed/);const message=f.manager.sendMessageAs(f.code,animus.player_code,'Trust me.');assert.equal(message.author,target.name,'message is attributed to the possessed target, not the Animus');}finally{f.close();}});

test('Animus: game-end reveal marks possessed:true ONLY for players who were actually possessed, not the whole roster',()=>{const f=fixture(9);try{f.manager.start(f.code,'p0');makeAnimus(f);f.manager.advance(f.code,'p0');const animus=f.manager.players(f.code).find(p=>p.role_id==='animus'),possessedTarget=f.manager.players(f.code).find(p=>p.faction==='loyalist');f.manager.db.prepare('UPDATE hr_players SET possessed_by=? WHERE game_code=? AND player_code=?').run(animus.player_code,f.code,possessedTarget.player_code);f.manager.db.prepare("UPDATE hr_games SET status='ended' WHERE code=?").run(f.code);const viewer=f.manager.players(f.code).find(p=>p.player_code!==animus.player_code&&p.player_code!==possessedTarget.player_code);const state=f.manager.state(f.code,viewer.player_code);const possessedRows=state.players.filter(p=>p.possessed);assert.deepEqual(possessedRows.map(p=>p.playerCode),[possessedTarget.player_code],'only the actually-possessed player is flagged, not every player in the ended game');const spectateState=f.manager.spectate(f.code);const spectatePossessedRows=spectateState.players.filter(p=>p.possessed);assert.deepEqual(spectatePossessedRows.map(p=>p.playerCode),[possessedTarget.player_code],'same guarantee for spectators');}finally{f.close();}});

